        let note = &RELEASE_NOTES[self.step];
        let (tag_bg, tag_fg): (Hsla, Hsla) = match note.tone {
            NoteTone::Emerald => {
                if dark {
                    (hsla(160. / 360., 0.84, 0.39, 0.14), rgb(0x34d399).into())
