            NoteTone::Blue => {
                if dark {
                    (hsla(217. / 360., 0.91, 0.60, 0.15), rgb(0x60a5fa).into())
                } else {
                    (hsla(217. / 360., 0.91, 0.60, 0.12), rgb(0x2563eb).into())
