                                            .text_color(title_fg)
                                            .child(lang.text("Release 2.4", "版本 2.4")),
                                    )
                                    .child(
                                        div()
                                            .text_size(px(12.))
                                            .line_height(px(18.))
                                            .text_color(sub_fg)
                                            .child(
                                                BlurCrossfade::label(sub_bx_id, sub_key, sub_label)
                                                    .with_morph(BlurMorph::None)
                                                    .with_blur_px(6.)
                                                    .with_duration_ms(340.),
                                            ),
                                    ),
                            )
                            .child(
                                div()
                                    .id(pub_btn_id)
                                    .role(Role::Button)
                                    .aria_label(pub_label)
                                    .tab_index(0)
                                    .h(px(30.))
                                    .px(px(12.))
                                    .rounded(px(9.))
                                    .bg(primary_bg)
                                    .text_color(primary_fg)
                                    .text_size(px(12.5))
                                    .line_height(px(18.))
                                    .font_weight(FontWeight::MEDIUM)
                                    .flex()
                                    .items_center()
