                                    .child(BlurCrossfade::label(pub_bx_id, pub_key, pub_label)),
                            ),
                    )
                    .child(
                        div()
                            .mt(px(15.))
                            .w_full()
                            .rounded(px(12.))
                            .bg(panel_bg)
                            .px(px(14.))
                            .py(px(12.))
                            .child(
                                BlurCrossfade::from_fn(note_bx_id, note.key, move |_, _| {
                                    div()
                                        .w_full()
                                        .flex()
                                        .flex_col()
                                        .items_start()
                                        .gap(px(6.))
                                        .child(
                                            div()
                                                .px(px(9.))
                                                .py(px(2.5))
                                                .rounded(px(999.))
                                                .bg(tag_bg)
