                                    .tab_index(0)
                                    .h(px(30.))
                                    .px(px(12.))
                                    .rounded(px(9.))
                                    .bg(chip_bg)
                                    .border_1()
                                    .border_color(chip_border)
                                    .text_color(chip_fg)
                                    .text_size(px(12.5))
                                    .line_height(px(18.))
                                    .font_weight(FontWeight::MEDIUM)
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .cursor_pointer()
                                    .hover(|s| s.opacity(0.85))
                                    .focus_visible(move |s| s.border_color(focus_ring))
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.next_step(cx);
                                    }))
                                    .child(lang.text("Next", "下一条")),
